    todynamic(strcat('["', replace_string(replace_string(_ExcIPs_raw, ' ', ''), ',', '","'), '"]')));
let _NLSel = dynamic([{NamedLocations}]);
let _NLActive = array_length(_NLSel) > 0;
let SigninLogs = SigninLogs
    | where _ExcIPs_raw == '' or isempty(IPAddress) or not(ipv4_is_in_any_range(IPAddress, _ExcIPs))
    | where not(_NLActive) or isempty(NetworkLocationDetails) or not(tostring(NetworkLocationDetails) has_any (_NLSel));
// Coordinated low-volume failures: many IPs each making only 1-3 failed attempts (slow/distributed brute-force)
let _t = SigninLogs
    | where TimeGenerated {TimeRange}
    | where ResultType != "0";
let perIP = _t
    | summarize Attempts = count(), Users = dcount(UserPrincipalName), TargetUsers = make_set(UserPrincipalName, 5) by IPAddress
    | where Attempts between (1 .. 3);
let coord = _t
    | where IPAddress in ((perIP | project IPAddress))
    | summarize
        DistinctAttackerIPs = dcount(IPAddress),
        TotalAttempts = count(),
        DistinctCountries = dcount(tostring(LocationDetails.countryOrRegion)),
        SampleIPs = make_set(IPAddress, 15),
        SampleCountries = make_set(tostring(LocationDetails.countryOrRegion), 10),
        FirstSeen = min(TimeGenerated),
        LastSeen = max(TimeGenerated)
      by UserPrincipalName
    | where DistinctAttackerIPs >= 10;
coord
| extend BotnetVerdict = case(
    DistinctAttackerIPs >= 100, "🔴 Critical - Coordinated Slow Brute-Force",
    DistinctAttackerIPs >= 30, "🟠 High - Distributed Low-and-Slow",
    "🟡 Suspicious")
| project BotnetVerdict, UserPrincipalName, DistinctAttackerIPs, TotalAttempts, DistinctCountries, SampleIPs, SampleCountries, FirstSeen, LastSeen
| order by DistinctAttackerIPs desc

let _ExcIPs_raw = '{ExcludedIPs}';
let _ExcIPs = iif(_ExcIPs_raw == '', dynamic([]),
    todynamic(strcat('["', replace_string(replace_string(_ExcIPs_raw, ' ', ''), ',', '","'), '"]')));
let _NLSel = dynamic([{NamedLocations}]);
let _NLActive = array_length(_NLSel) > 0;
let SigninLogs = SigninLogs
    | where _ExcIPs_raw == '' or isempty(IPAddress) or not(ipv4_is_in_any_range(IPAddress, _ExcIPs))
    | where not(_NLActive) or isempty(NetworkLocationDetails) or not(tostring(NetworkLocationDetails) has_any (_NLSel));
// Botnet Activity Timeline (distinct IPs vs failed attempts per hour)
SigninLogs
| where TimeGenerated {TimeRange}
| where ResultType != "0"
| summarize
    DistinctIPs = dcount(IPAddress),
    Failures = count(),
    DistinctUsers = dcount(UserPrincipalName)
  by bin(TimeGenerated, 1h)
| order by TimeGenerated asc
| render timechart
